// extract out the base rating contribution to the base stat to get the true base (baseAdj)
const base = GetStat(GetOwner(), $#10516612381411111:109343399171813$);
const baseRating = GetStat(GetInstigator(), $#10516612381411111:109343183951489$);
const baseCoeff = EvalE($#10516612381411112:6064634020099129392$);
const mult = EvalE($#10516612381411112:6064633140807796314$);
const baseAdj = base / (1.0 - baseRating / (baseRating * mult + baseCoeff));

// calculate total rating including the base rating but reduced by the coefficient quotient
const coeff = EvalE($#10516612381411112:6064634082164342792$);
const rating = baseRating * coeff/baseCoeff + GetStat(GetInstigator(), $#10516612381411111:109343183951493$);

// calc final stat value
baseAdj * (1.0 - rating / (rating * mult + coeff))
